CREATE TABLE IF NOT EXISTS audit_status_reports(id TEXT PRIMARY KEY,audit_id TEXT NOT NULL,header_json TEXT NOT NULL,snapshot_sha256 TEXT NOT NULL,item_count INTEGER NOT NULL,input_sha256 TEXT NOT NULL,write_token TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_status_reports_parent_idx ON audit_status_reports(audit_id,created_at,id);
CREATE TABLE IF NOT EXISTS audit_status_report_items(report_id TEXT NOT NULL,kind TEXT NOT NULL,id TEXT NOT NULL,record_json TEXT NOT NULL,PRIMARY KEY(report_id,kind,id));
CREATE TABLE IF NOT EXISTS audit_report_source_revision(id INTEGER PRIMARY KEY CHECK(id=1),revision TEXT NOT NULL);
INSERT OR IGNORE INTO audit_report_source_revision(id,revision) VALUES(1,lower(hex(randomblob(16))));
CREATE TRIGGER IF NOT EXISTS audit_report_simple_audits_insert AFTER INSERT ON simple_audits WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_audits_update AFTER UPDATE ON simple_audits WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_audits_delete AFTER DELETE ON simple_audits WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_records_insert AFTER INSERT ON simple_grc_records WHEN NEW.module='Denetim Yönetimi' BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_records_update AFTER UPDATE ON simple_grc_records WHEN OLD.module='Denetim Yönetimi' OR NEW.module='Denetim Yönetimi' BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_records_delete AFTER DELETE ON simple_grc_records WHEN OLD.module='Denetim Yönetimi' BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_record_codes_insert AFTER INSERT ON simple_grc_record_codes WHEN NEW.module='Denetim Yönetimi' BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_record_codes_update AFTER UPDATE ON simple_grc_record_codes WHEN OLD.module='Denetim Yönetimi' OR NEW.module='Denetim Yönetimi' BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_record_codes_delete AFTER DELETE ON simple_grc_record_codes WHEN OLD.module='Denetim Yönetimi' BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_metadata_insert AFTER INSERT ON simple_grc_metadata WHEN (substr(NEW.key,1,11)='audit_plan_' OR substr(NEW.key,1,14)='audit_catalog_') BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_metadata_update AFTER UPDATE ON simple_grc_metadata WHEN (substr(OLD.key,1,11)='audit_plan_' OR substr(OLD.key,1,14)='audit_catalog_') OR (substr(NEW.key,1,11)='audit_plan_' OR substr(NEW.key,1,14)='audit_catalog_') BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_simple_grc_metadata_delete AFTER DELETE ON simple_grc_metadata WHEN (substr(OLD.key,1,11)='audit_plan_' OR substr(OLD.key,1,14)='audit_catalog_') BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_audit_request_workflows_insert AFTER INSERT ON audit_request_workflows WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_audit_request_workflows_update AFTER UPDATE ON audit_request_workflows WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_audit_request_workflows_delete AFTER DELETE ON audit_request_workflows WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_audit_requests_insert AFTER INSERT ON audit_requests WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_audit_requests_update AFTER UPDATE ON audit_requests WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_audit_requests_delete AFTER DELETE ON audit_requests WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_enterprise_findings_insert AFTER INSERT ON enterprise_findings WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_enterprise_findings_update AFTER UPDATE ON enterprise_findings WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
CREATE TRIGGER IF NOT EXISTS audit_report_enterprise_findings_delete AFTER DELETE ON enterprise_findings WHEN 1 BEGIN UPDATE audit_report_source_revision SET revision=lower(hex(randomblob(16))) WHERE id=1; END;
